examples.template:
HStack(spacing: 0) {
    Button({{label}}) {}
        .buttonStyle(.monarch({{variant|case}}))
    Rectangle().fill(theme.colors.accentOnSolid.opacity(0.5)).frame(width: 1)
    Menu {
        Button({{items.0}}) {}
        Button({{items.1}}) {}
    } label: {
        MonarchIcon(systemName: "chevron.down", size: .sm)
    }
    .buttonStyle(.monarch({{variant|case}}))
    .accessibilityLabel("More options for " + {{label}})
}
.background(theme.colors.accentSolid)
.clipShape(RoundedRectangle(cornerRadius: theme.radius.md, style: .continuous))
.accessibilityElement(children: .contain)
.accessibilityLabel({{label}})

